import{_ as r,C as i,o as d,c,j as o,a as t,E as a,a2 as n}from"./chunks/framework.sc8Z_ZE3.js";const f=JSON.parse('{"title":"Build your knowledge, step by step","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/guide.md","filePath":"knowledge/guide.md"}'),h={name:"knowledge/guide.md"};function l(p,e,u,g,w,m){const s=i("Badge");return d(),c("div",null,[e[4]||(e[4]=o("h1",{id:"build-your-knowledge-step-by-step",tabindex:"-1"},[t("Build your knowledge, step by step "),o("a",{class:"header-anchor",href:"#build-your-knowledge-step-by-step","aria-label":'Permalink to "Build your knowledge, step by step"'},"​")],-1)),a(s,{type:"built",text:"Built"}),e[5]||(e[5]=t(" Connect your team's sources, keep them in sync, and let people and agents answer with cited sources. The sources and the search page are built; agents searching knowledge is ",-1)),a(s,{type:"tried",text:"In real runs"}),e[6]||(e[6]=n('.<p>Agents work from what your team has already written down: pages, tickets, code, manuals. Octryx AI reads these sources per Workspace, keeps every version it read, and makes them searchable for people and agents. Every answer links the passage it comes from, so you can open the source and check it before you rely on it.</p><p>The example is the Workspace <strong>Demo Shop</strong>, an online shop team with the Confluence space <code>SHOP</code>, the Jira project <code>OCX</code>, the repository <code>demo-shop/checkout</code> and two PDFs.</p><h2 id="_1-open-knowledge-›-sources" tabindex="-1">1. Open Knowledge › Sources <a class="header-anchor" href="#_1-open-knowledge-›-sources" aria-label="Permalink to &quot;1. Open Knowledge › Sources&quot;">​</a></h2><p>Open the <strong>Knowledge</strong> area of your Workspace and choose <strong>Sources</strong>. The page lists each source with its kind, what it reads, how many items it holds, its last sync and its state: <strong>Up to date</strong>, <strong>Synced</strong>, <strong>Syncing</strong>, <strong>Out of date</strong>, <strong>Needs attention</strong>, <strong>Paused</strong> or <strong>Never synced</strong>. Adding the first source turns Knowledge on for the Workspace. Only platform admins and the Workspace&#39;s admins and owners see this page.</p><h2 id="_2-connect-confluence" tabindex="-1">2. Connect Confluence <a class="header-anchor" href="#_2-connect-confluence" aria-label="Permalink to &quot;2. Connect Confluence&quot;">​</a></h2><p>A platform admin, or a Workspace admin for their own Workspaces, sets up the connection once under <strong>Admin › Connections</strong>, with the Confluence URL, the sign-in and the Workspaces it is <strong>Available in</strong>.</p><p>Then, under <strong>Knowledge › Sources › Add source</strong>, pick <strong>Confluence</strong> and name whole spaces by key (here <code>SHOP</code>) or page trees. Pages are synced; attachments and comments are not. Choose a schedule: manual, every 15 minutes, hourly, every 4 hours, daily at 06:00, or a custom schedule (at most every 15 minutes).</p>',8)),o("p",null,[e[0]||(e[0]=t("Restricted pages are withheld by default. ",-1)),a(s,{type:"built",text:"Built"}),e[1]||(e[1]=t(" A platform admin can turn on ",-1)),e[2]||(e[2]=o("strong",null,"Enforce source permissions in this Workspace",-1)),e[3]||(e[3]=t(" on the Sources page. The change needs a reason and is recorded in the audit log. From the next sync on, restricted pages are indexed and found only by the people Confluence lets read them.",-1))]),e[7]||(e[7]=n('<h2 id="_3-connect-jira" tabindex="-1">3. Connect Jira <a class="header-anchor" href="#_3-connect-jira" aria-label="Permalink to &quot;3. Connect Jira&quot;">​</a></h2><p>Add a source of kind <strong>Jira</strong> with one or more project keys (here <code>OCX</code>). An optional JQL filter can only narrow the project scope, never widen it. Each issue becomes a document with its key in the title, for example &quot;OCX-14: Raise the free-shipping threshold to 60.00&quot;, so agents can cite the ticket.</p><p>Issues with a Jira security level are always withheld, even when the Workspace enforces source permissions. Separately from Knowledge, Jira and ServiceNow are polled every 5 minutes for changes that can start a workflow.</p><h2 id="_4-add-a-code-repository" tabindex="-1">4. Add a code repository <a class="header-anchor" href="#_4-add-a-code-repository" aria-label="Permalink to &quot;4. Add a code repository&quot;">​</a></h2><p>Code comes in two ways:</p><ul><li>A <strong>Git repository</strong> source reads a public repository on github.com, or a Bitbucket repository (Cloud, Server or Data Center) through its connection, at a branch or tag. Private GitHub and GitLab repositories are not read directly yet; use the local snapshot below.</li><li>A developer who starts <code>octryx-claude</code> in a checkout uploads the files at <code>HEAD</code> as a local snapshot, if the Workspace allows local snapshots. This is off by default; a Workspace admin or owner turns it on.</li></ul><p>Text files are indexed with line ranges and secrets are redacted, so an agent can answer &quot;Where is the free-shipping threshold configured?&quot; with a link to <code>config/shipping.yaml</code>.</p><h2 id="_5-upload-pdfs-and-documents" tabindex="-1">5. Upload PDFs and documents <a class="header-anchor" href="#_5-upload-pdfs-and-documents" aria-label="Permalink to &quot;5. Upload PDFs and documents&quot;">​</a></h2><p>Under <strong>Knowledge › Documents › Add document</strong>, upload PDF, Word, PowerPoint, Excel or HTML up to 32 MB, or text up to 8 MB. PDF, Office and HTML files are parsed in the background, in an isolated parser without network access.</p><p>Passages keep their page and section: a citation reads like &quot;p. 4, § 3 Shipping rules&quot;. If you upload again with the same source key, Octryx AI adds a new revision, and you can compare revisions under <strong>Diff</strong>.</p><p>Parsing PDF, Office and HTML files needs the parser service installed with the instance.</p><h2 id="_6-add-research-websites" tabindex="-1">6. Add research websites <a class="header-anchor" href="#_6-add-research-websites" aria-label="Permalink to &quot;6. Add research websites&quot;">​</a></h2><p><strong>Knowledge › Research websites</strong> sets which sites agents may use when they research the web for this Workspace. You approve or block each site, and choose the search mode: <strong>Open (blocked websites excluded)</strong> or <strong>Approved websites only</strong>. Research always reads only approved sites. Websites are not synced like Confluence. Web pages only become knowledge through a <strong>Package</strong>, after an author approves them.</p><p>Web search needs a search provider set up by a platform administrator. Without one, the page says that no search provider is configured.</p><h2 id="_7-watch-the-sync" tabindex="-1">7. Watch the sync <a class="header-anchor" href="#_7-watch-the-sync" aria-label="Permalink to &quot;7. Watch the sync&quot;">​</a></h2><p>Open a source to see its <strong>Overview</strong>, <strong>Setup</strong>, <strong>Runs</strong> and <strong>Freshness</strong>. A run says how many items it listed, created, updated, left unchanged, retired, skipped or failed, and lists the items it handled. <strong>Sync now</strong> syncs the source right away. A page that was deleted at the source is marked <strong>Removed at source</strong> and is no longer found.</p><p>Scheduled syncs need the instance&#39;s sync scheduler switched on. Without it, only <strong>Sync now</strong> syncs.</p><h2 id="_8-search" tabindex="-1">8. Search <a class="header-anchor" href="#_8-search" aria-label="Permalink to &quot;8. Search&quot;">​</a></h2><p>Open <strong>Knowledge › Search</strong> and ask a question in any language. Results are passages grouped by where they come from (documents, code, Jira, Confluence), with filters for source, space or project, and time. Above the passages, Octryx AI writes a short answer whose sentences link the passages by number. <strong>Ask in chat</strong> carries the question and the sources into a new chat.</p><p>Relevance ranking is optional. Without a reranker, the page says <strong>Relevance ranking unavailable</strong> and ranks by keywords and meaning only.</p><h2 id="_9-explore-the-graph" tabindex="-1">9. Explore the graph <a class="header-anchor" href="#_9-explore-the-graph" aria-label="Permalink to &quot;9. Explore the graph&quot;">​</a></h2><p><strong>Knowledge › Explore</strong> answers &quot;what is connected to what&quot;. The <strong>List</strong> view shows relationships with the statement they were read from. The <strong>Graph</strong> view (admins) draws entities by type with a legend that is also a type filter, plus zoom, fit and a count line.</p><p>Admins build the rule-based manual, configuration and operations layers under <strong>Knowledge › Advanced › Structured graph</strong>. If a Workspace holds only documents and chapters so far, the graph shows those with a note saying so.</p><h2 id="_10-use-it-in-chat-and-in-workflows" tabindex="-1">10. Use it in chat and in workflows <a class="header-anchor" href="#_10-use-it-in-chat-and-in-workflows" aria-label="Permalink to &quot;10. Use it in chat and in workflows&quot;">​</a></h2><p>Ask in chat. The agent searches the Workspace&#39;s knowledge, answers, and links each statement to its source.</p><p>Under the answer, the <strong>Sources · 4</strong> button (the number is the count of cited sources) opens <strong>Sources &amp; evidence</strong>, the list of the cited sources.</p><p>The same search serves research steps in workflows, sub-agents and coding agents connected over MCP. If an answer cites none of the sources the agent found, the agent is reminded once to cite them; statements still without a source are marked in the answer.</p><h2 id="_11-advanced-optional" tabindex="-1">11. Advanced (optional) <a class="header-anchor" href="#_11-advanced-optional" aria-label="Permalink to &quot;11. Advanced (optional)&quot;">​</a></h2><p>All built, admins only, under <strong>Knowledge › Advanced</strong>:</p><ul><li><strong>Packages</strong>: an agent researches a topic on trusted sites, and you approve what gets ingested.</li><li><strong>Bindings</strong>: which other Workspaces this Workspace reads, and who reads this one; search reads across, nothing is copied.</li><li><strong>Changes</strong>: what changed between two versions of a product, as cited facts.</li><li><strong>Memory</strong>: what agents remember for the Workspace, and who may see it.</li><li><strong>Episodes</strong>: whether sessions may return what they learned as episodes.</li><li><strong>Engineering knowledge</strong>: versioned engineering packs the coding agent applies to changes.</li><li><strong>Structured graph</strong>: the rule-based layers of the knowledge graph.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/work/chat">Chat</a></li></ul>',32))])}const k=r(h,[["render",l]]);export{f as __pageData,k as default};
